function unavailable(){return empty('Conteúdo indisponível nesta cidade','Volte para a página inicial ou selecione a cidade em que o conteúdo foi publicado.','location_off','home','Ir para o início');}
// Rodada 49: conteúdo removido pela moderação não abre por Salvos, conversa ou endereço direto.
function removedContent(kind){return empty(kind==='ask'?'Pergunta removida':'Anúncio removido','A moderação do Bivaque removeu este conteúdo depois de denúncias.','report','home','Ir para o início');}
function renderItem(){
 const i=itemById(route.id);if(i?.status==='removed')return removedContent('item');if(!accessibleRecord(i))return unavailable();
 const photos=i.photos.map(image).filter(Boolean),sold=i.status==='sold';
 actionsBar(`${iconBtn(i.saved?'bookmark':'bookmark_border','save-item',i.id,i.saved?'Remover dos salvos':'Salvar anúncio',`aria-pressed="${!!i.saved}"`)}${iconBtn('share','share',`anuncio|${i.id}`,'Compartilhar anúncio')}${i.mine?btn('Editar anúncio','edit-item',i.id,'filled','edit'):btn(sold?'Indisponível':'Tenho interesse','item-interest',i.id,'filled','chat_bubble').replace('<md-filled-button','<md-filled-button '+(sold?'disabled':''))}`);
 return `<div class="detail-layout"><div><div class="detail-hero" id="listing-hero">${photos[0]?`<img src="${photos[0]}" alt="${esc(i.title)}" id="hero-image"><button type="button" class="hero-zoom" data-action="lightbox" data-value="item">${icon('image')}Ver fotos${photos.length>1?` (${photos.length})`:''}</button>`:`<div class="photo-fallback" style="height:100%;display:grid;place-items:center">${icon('photo_camera')}</div>`}<span class="pill">${sold?(i.kind==='imovel'?'Indisponível':'Vendido'):i.kind==='imovel'?'Imóvel':'Desapego'}</span></div>${photos.length>1?`<div class="gallery" aria-label="Galeria de fotos">${photos.map((p,n)=>`<button type="button" data-action="gallery" data-value="${n}" class="${n===0?'selected':''}" aria-label="Ver foto ${n+1}"><img src="${p}" alt="Foto ${n+1} de ${esc(i.title)}"></button>`).join('')}</div>`:''}${i.demo&&photos.length?'<p class="labelled-example">Foto ilustrativa do anúncio de exemplo.</p>':''}<div class="detail-title"><div class="price">${money(i.numPrice)}${i.per?'<small> / mês</small>':''}</div><h1>${esc(i.title)}</h1><p class="muted small">${esc(i.hood)} · ${esc(i.city)}${i.mine?' · seu anúncio':''}</p></div>${i.kind==='imovel'?propertyDetailHtml(i):itemDetailHtml(i)}<section class="section">${sectionTitle('Sobre o anúncio')}<p class="detail-copy">${esc(i.desc)}</p></section><section class="section">${sectionTitle('Localização aproximada')}<div class="context-strip readonly" style="margin-top:0">${icon('location_on')}<span class="grow">${esc(i.hood)}, ${esc(i.city)}<br><span class="tiny">O endereço exato pode ser combinado na conversa.</span></span>${btn('Ver bairro','map',`${i.hood}|${i.city}`,'text')}</div></section></div><aside class="detail-aside"><div class="seller"><span class="avatar ${i.mine?'me':''}">${esc(i.mine?initals(state.profile.name):i.sini||initals(i.seller))}</span><div><b>${esc(i.mine?state.profile.name:i.seller)}</b><span class="small muted">${esc(i.note||'Membro da comunidade')}</span>${verifiedBadgeHtml()}</div></div>${i.mine?`<div class="metric-grid"><div class="metric"><b>${i.views||0}</b><span>visitas</span></div><div class="metric"><b>${state.threads.filter(t=>t.about.type==='item'&&t.about.id===i.id).length}</b><span>conversas</span></div><div class="metric"><b>${sold?'Encerrado':'Ativo'}</b><span>situação</span></div></div><section class="section"><div class="stack">${btn(sold?'Reativar anúncio':i.kind==='imovel'?'Marcar indisponível':'Marcar como vendido','item-status',i.id,'outlined',sold?'refresh':'check_circle')}${btn('Ver interessados','item-leads',i.id,'outlined','chat_bubble')}${btn('Excluir anúncio','delete-item',i.id,'text','delete').replace('<md-text-button','<md-text-button class="danger"')}</div></section>`:`<div class="stack">${btn('Fazer uma oferta','item-offer',i.id,'outlined','sell')}${btn(i.kind==='imovel'?'Combinar visita':'Perguntar sobre retirada','item-visit',i.id,'outlined','event')}${btn('Denunciar anúncio','report',`item|${i.id}`,'text','flag')}</div>`}</aside></div>`;
}
